function validate([piles]) {
  if (!Array.isArray(piles) || piles.length < 1 || piles.length > 7) return 'piles needs 1 to 7 values.';
  if (piles.some(v => !Number.isInteger(v) || v < 1 || v > 7)) return 'Each pile holds 1 to 7 stones.';
  return null;
}

