function nimGame(piles) {
  const memo = new Map();
  const canWin = state => {
    const key = state.join(',');
    if (memo.has(key)) return memo.get(key);
    let result = false;
    for (let i = 0; i < state.length && !result; i++) {
      for (let take = 1; take <= state[i] && !result; take++) {
        const after = state.slice();
        after[i] -= take;
        if (!canWin(after.filter(x => x > 0).sort((a, b) => a - b))) result = true;
      }
    }
    memo.set(key, result);
    return result;
  };
  return canWin(piles.slice().sort((a, b) => a - b));
}

