function generate(rand, size) {
  const n = size === 'large' ? 7 : 1 + Math.floor(rand() * 5);
  const piles = Array.from({ length: n }, () => 1 + Math.floor(rand() * 7));
  // Make roughly a third of the inputs losing positions for Alice.
  if (n > 1 && rand() < 0.35) {
    let rest = 0;
    for (let i = 1; i < n; i++) rest ^= piles[i];
    if (rest >= 1 && rest <= 7) piles[0] = rest;
  }
  return [piles];
}
